'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('noir:'+key))??fallback}catch{return fallback}};
const write=(key,val)=>{try{localStorage.setItem('noir:'+key,JSON.stringify(val))}catch{toast('Your browser could not save this change.')}};
let catalog=[],tvCatalog=[],activeCatalog=[],heroIndex=0,nav='Movies',filter='All',query='',saved=read('saved',[]),recent=read('recent',[]),playing=null,provider=read('provider','ScreenScape'),searchController,searchVersion=0,detailMovie=null,searchTimer;
if(!Array.isArray(saved))saved=[];if(!Array.isArray(recent))recent=[];
if(!NoirProviders.get(provider)||NoirProviders.get(provider).restricted)provider='ScreenScape';
