const allKnown=new Map();
function normalize(m){return {...m,type:m.type==='series'?'tv':m.type||'movie',genres:(m.genres||m.genre||[]).map(g=>g==='Sci-Fi'?'Science Fiction':g),year:m.year||m.releaseInfo||'',tmdb:m.tmdb||m.moviedb_id};}
function register(ms){return ms.map(normalize).filter(m=>m.id&&m.name).map(m=>{allKnown.set(m.id,m);return m})}
function img(m,kind='poster'){const value=m[kind];return typeof value==='string'&&value.startsWith('https://')?value:''}
function image(m,kind='poster',loading='lazy'){return `<img src="${escapeHTML(img(m,kind))}" alt="${kind==='poster'?escapeHTML(m.name):''}" loading="${loading}" decoding="async" onerror="this.style.opacity='0'">`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function isSaved(m){return saved.some(x=>x.id===m.id)}
function save(m){if(isSaved(m)){saved=saved.filter(x=>x.id!==m.id);toast('Removed from your list')}else{saved.push(m);toast('Added to your list')}write('saved',saved);$('#listCount').textContent=saved.length;if(detailMovie?.id===m.id){const button=$('#detail .title-save');if(button)button.textContent=isSaved(m)?'✓ Saved to my list':'+ Add to my list'}if(nav==='Watchlist')renderCards();renderHero()}
function heroMovies(){return catalog.slice(0,4)}
function renderHero(){let m=heroMovies()[heroIndex];if(!m)return;$('.ambient').style.backgroundImage=`linear-gradient(115deg,rgba(5,8,13,.76),rgba(6,10,16,.55)),url("${img(m,'background')}")`;$('#hero').innerHTML=`${image(m,'background','eager').replace('<img ', '<img class="hero-image" ')}<div class="trending"><i></i> Now trending</div><div class="hero-counter">${heroMovies().map((_,i)=>`<b class="${i===heroIndex?'on':''}"></b>`).join('')}</div><div class="hero-content"><div class="tags">${m.genres.slice(0,2).map(g=>`<span class="tag">${escapeHTML(g)}</span>`).join('')}</div><h2>${escapeHTML(m.name).replace(': ',':<br>')}</h2><p>${escapeHTML(m.description?.slice(0,190))}${m.description?.length>190?'…':''}</p><div class="actions"><button class="watch" data-action="watch" data-id="${m.id}"><span>▶</span> Watch now</button><button class="outline" data-action="save" data-id="${m.id}"><span>${isSaved(m)?'✓':'+'}</span> ${isSaved(m)?'In my list':'My watchlist'}</button><button class="icon" data-action="detail" data-id="${m.id}" aria-label="Movie details">···</button></div></div><div class="hero-arrows"><button data-slide="-1" aria-label="Previous featured movie">‹</button><button data-slide="1" aria-label="Next featured movie">›</button></div>`}
function card(m){return `<button class="card" data-action="${nav==='Watching'?'watch':'detail'}" data-id="${escapeHTML(m.id)}" aria-label="${nav==='Watching'?'Resume':'View'} ${escapeHTML(m.name)}">${image(m)}<span class="card-more">···</span><div class="card-content"><span class="tag">${escapeHTML(m.genres[0]||'Cinema')}</span><h3>${escapeHTML(m.name)}</h3><div class="card-meta">${nav==='Watching'?(m.type==='tv'?'S'+(m.season||1)+' · E'+(m.episode||1)+' · ':'')+(m.position>0?Math.floor(m.position/60)+' min watched':'Recently opened'):escapeHTML(m.year)}${m.imdbRating?' &nbsp; ★ '+escapeHTML(m.imdbRating):''}</div><div class="card-bottom"><p>${escapeHTML(m.description||'Find your next great story.')}</p><span class="play-circle">▶</span></div></div></button>`}
function revealCatalogue(){const el=$('#cards');el.getAnimations().forEach(a=>a.cancel());if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{opacity:.45,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.7,.2,1)'})}
function renderCards(){let ms=query?activeCatalog:nav==='Watching'?recent:nav==='Watchlist'?saved:nav==='TV Series'?tvCatalog:catalog;let category=nav==='Animation'?'Animation':nav==='Mystery'?'Mystery':filter;if(category!=='All')ms=ms.filter(m=>m.genres.includes(category));const markup=ms.map(card).join('');if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.querySelector('dialog[open]')){document.startViewTransition(()=>{$('#cards').innerHTML=markup}).finished.catch(()=>{})}else{$('#cards').innerHTML=markup;revealCatalogue()}$('#sectionTitle').textContent=query?`Results for “${query}”`:nav==='Watching'?'Currently watching':nav==='Watchlist'?'Your watchlist':nav==='TV Series'?'One more episode':nav==='Animation'?'A world of imagination':nav==='Mystery'?'Keep them guessing':'You might like';$('#sectionEyebrow').textContent=query?`${ms.length} TITLES FOUND`:nav==='Watching'?'PICK UP WHERE YOU LEFT OFF':nav==='Watchlist'?'SAVED FOR A GOOD NIGHT':'CURATED FOR YOUR EVENING';$('#status').textContent=!ms.length?(nav==='Watching'?'Start a movie or episode and it will appear here.':nav==='Watchlist'?'Your list starts here. Open a movie and tap “My watchlist”.':query?'No matching titles found. Try a different title.':'No titles in this category yet.') : '';$('#filters').hidden=['Watching','Watchlist','Animation','Mystery'].includes(nav);}
function renderTrailers(){$('#trailers').innerHTML=catalog.filter(m=>m.trailerStreams?.length||m.trailers?.length).slice(1,4).map(m=>`<button class="trailer" data-action="trailer" data-id="${m.id}">${image(m,'background')}<span class="trailer-info"><strong>${escapeHTML(m.name)}</strong><span class="small-play">▶</span></span></button>`).join('')}
function renderRecent(){$('#recent').innerHTML=recent.length?recent.slice(0,4).map(m=>`<button class="recent-item" data-action="watch" data-id="${escapeHTML(m.id)}">${image(m)}<div><strong>${escapeHTML(m.name)}</strong><small>${m.position>0?Math.floor(m.position/60)+' min watched':'Recently opened'}</small></div><span class="small-play">▶</span></button>`).join(''):'<p class="empty-recent">Your next movie night starts here. Pick a film and we’ll keep it close.</p>';$('#listCount').textContent=saved.length;}
function trailerIds(m){return [...new Set([...(m.trailerStreams||[]).map(t=>t.ytId),...(m.trailers||[]).map(t=>t.source)])].filter(id=>/^[\w-]{11}$/.test(id))}
function renderDetail(m){
 detailMovie=m;const longest=Math.max(...m.name.split(/\s+/).map(w=>w.length));$('#detail').style.setProperty('--title-desktop',Math.min(m.name.length>32?3.8:m.name.length>24?5:7.5,75/longest)+'vw');$('#detail').style.setProperty('--title-mobile',Math.min(14,130/longest)+'vw');const ids=trailerIds(m).slice(0,3);const related=catalog.filter(x=>x.id!==m.id&&x.genres.some(g=>m.genres.includes(g))).slice(0,5);
 $('#detail').classList.add('title-page');NoirThemes.apply($('#detail'),m);
 $('#detailContent').innerHTML=`<div class="title-scene"><img class="title-art" src="${escapeHTML(img(m,'background'))}" alt="" decoding="async"><div class="scene-shade"></div><header class="title-nav"><button class="title-brand" data-close="detail" aria-label="Back to catalogue">NOIR<span>YOUR PERSONAL CINEMA</span></button><div class="title-breadcrumb">${m.type==='tv'?'SERIES':'FILM'} <span>/</span> ${escapeHTML(m.genres[0]||'CINEMA')}</div><button class="liquid-control title-back" data-close="detail">← Catalogue</button></header><div class="title-stage"><div class="title-negative-space"><span class="vertical-caption">A NOIR MOVIE NIGHT</span></div><div class="title-story"><span class="title-kicker">${m.type==='tv'?'THE SERIES':'THE FEATURE'}</span><h2 class="cinema-title ${m.name.length>24?'long-title':''}">${escapeHTML(m.name)}</h2><div class="title-summary"><p>${escapeHTML(m.description||'A new story awaits.')}</p><div class="title-facts"><span>${escapeHTML(m.year)}</span>${m.runtime?`<span>${escapeHTML(m.runtime)}</span>`:''}${m.imdbRating?`<span>★ ${escapeHTML(m.imdbRating)}</span>`:''}<span>${escapeHTML(m.genres.slice(0,2).join(' / '))}</span></div><button class="liquid-control title-save" data-action="save" data-id="${m.id}">${isSaved(m)?'✓ Saved to my list':'+ Add to my list'}</button></div></div></div><div class="title-bottom"><button class="cinema-watch" data-action="${m.type==='tv'?'episodes':'watch'}" data-id="${m.id}"><span class="watch-orbit"><span>▶</span></span><span>${m.type==='tv'?'Watch the series':'Watch the movie'}<small>${m.type==='tv'?'CHOOSE YOUR EPISODE':'SETTLE IN. PRESS PLAY.'}</small></span></button>${m.type==='tv'?'<section id="titleEpisodes" class="title-episodes title-extras" aria-label="Series episodes"></section>':`<section class="title-extras" aria-label="Trailers and similar titles"><div class="extras-heading"><h3>${ids.length?'Trailers':'More like this'}</h3><span>${String((ids.length?ids:related.slice(0,3)).length).padStart(2,'0')} / SELECTED</span></div><div class="trailer-rail">${ids.length?ids.map((id,i)=>`<button class="cinema-trailer" style="background-image:url('${escapeHTML(img(m,'background'))}')" data-action="trailer" data-id="${m.id}" data-trailer="${i}" aria-label="Watch trailer ${i+1} for ${escapeHTML(m.name)}"><img src="https://i.ytimg.com/vi/${id}/hqdefault.jpg" alt="" loading="lazy" onerror="this.remove()"><span class="trailer-glaze"></span><span class="trailer-play">▷</span><span class="trailer-number">0${i+1}</span><span class="trailer-caption">${i===0?'Official trailer':'Trailer '+(i+1)}</span></button>`).join(''):related.slice(0,3).map((x,i)=>`<button class="cinema-trailer" data-action="detail" data-id="${x.id}">${image(x,'background')}<span class="trailer-glaze"></span><span class="trailer-number">0${i+1}</span><span class="trailer-caption">${escapeHTML(x.name)}</span></button>`).join('')}</div></section>`}</div></div><div class="title-afterword"><div><span>THE PEOPLE BEHIND THE STORY</span><p>${escapeHTML((m.director||[]).join(', ')||'Explore the cast & story')}</p></div><div><span>STARRING</span><p>${escapeHTML((m.cast||[]).slice(0,5).join(' · ')||m.name)}</p></div></div>`;
 window.NoirLens?.mount($('#detail .title-scene'));
 if(m.type==='tv')window.NoirEpisodeUI?.mountDetail(m);
}
async function showDetail(m){renderDetail(m);if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;if(!m.tmdb||!m.description||!m.background||!m.genres.length){try{let data=await getMeta(m);if(detailMovie?.id===m.id)renderDetail(data)}catch{}}}
async function getMeta(m){if(m.type==='tv'){const state=await NoirEpisodes.load(m);const updated=register([{...m,...state.meta}])[0];if(updated)return updated}let r=await fetch(`https://v3-cinemeta.strem.io/meta/${m.type==='tv'?'series':'movie'}/${encodeURIComponent(m.id)}.json`,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Metadata unavailable');let d=await r.json();let updated=register([{...m,...d.meta}])[0];if(!updated)throw Error('No metadata');return updated}
function remember(m){let prev=recent.find(x=>x.id===m.id);const {videos,...brief}=m;recent=[{...brief,position:prev?.season===Number($('#season').value)&&prev?.episode===Number($('#episode').value)?prev.position:0,provider:prev?.provider,season:Math.max(1,Number($('#season').value)||1),episode:Math.max(1,Number($('#episode').value)||1)},...recent.filter(x=>x.id!==m.id)].slice(0,12);write('recent',recent);renderRecent()}
function providerURL(m){const season=Number($('#season').value),episode=Number($('#episode').value),last=recent.find(x=>x.id===m.id);const position=last&&(!last.provider||last.provider===provider)&&(m.type!=='tv'||(last.season===season&&last.episode===episode))?last.position:0;return NoirProviders.build(provider,m,season,episode,position)}
function setSourceStatus(text){$('#sourceStatus').textContent=text}
let presentationMovie=null;
function setPlayerPresentation(m){presentationMovie=m;NoirThemes.apply($('#player'),m);$('#playerBackdrop').src=img(m,'background');$('#sourceLabel').textContent=provider;$('#sourceToggle').hidden=false;setSourcesExpanded(false)}
function setSourcesExpanded(expanded){$('#sourceToggle').setAttribute('aria-expanded',String(expanded));$('.sourcebar').dataset.expanded=String(expanded);$('.playback-status').dataset.expanded=String(expanded)}
$('#sourceToggle').onclick=()=>setSourcesExpanded($('#sourceToggle').getAttribute('aria-expanded')!=='true');
document.addEventListener('noir:open-sources',()=>setSourcesExpanded(true));
document.addEventListener('noir:episode-selected',e=>watch(e.detail.show,e.detail.episode));
function showEpisodeChoices(m){window.NoirEpisodeUI?.revealDetail(m)}
$('#backToTitle').onclick=()=>{const m=presentationMovie;$('#player').close();if(m)showDetail(m)};
function loadPlayer(){
 if(!playing)return;clearTimeout(sourceTimer);$('#sourceLabel').textContent=provider;window.NoirLoading?.show(playing);window.NoirEpisodeUI?.setPlayer(playing,Number($('#season').value),Number($('#episode').value));
 const url=providerURL(playing);
 $$('[data-provider]').forEach(b=>{const selected=b.dataset.provider===provider;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});
 if(NoirProviders.get(provider)?.restricted){window.NoirLoading?.hide();$('#screen').innerHTML='<div class="notice"><h2>Stellar requires redirects to be allowed</h2><p>This provider refuses to run inside a restricted player. NOIR is keeping pop-ups and page redirects blocked. Choose ScreenScape or another source above.</p></div>';setSourceStatus('Stellar is incompatible with redirect protection');return}
 if(!url){window.NoirLoading?.hide();$('#screen').innerHTML='<div class="notice"><h2>This title isn’t linked yet</h2><p>No valid movie or episode identifier is available. Try another title.</p></div>';setSourceStatus('Source unavailable');return}
 const f=document.createElement('iframe');f.id='movieFrame';f.title=playing.name+' — '+provider;
 f.setAttribute('sandbox',NoirProviders.sandbox);
 f.allow='autoplay; fullscreen; picture-in-picture; encrypted-media';f.allowFullscreen=true;
 f.referrerPolicy='strict-origin-when-cross-origin';f.src=url;
 setSourceStatus('Opening '+provider+'…');window.NoirLoading?.opening(provider);
 f.addEventListener('load',()=>{if($('#movieFrame')!==f)return;window.NoirLoading?.opened();setSourceStatus(provider+' player opened · press play if needed');if(provider==='Stellar')f.contentWindow?.postMessage({type:'STELLAR_EMBED_INIT'},'https://stellar.rip')});
 f.addEventListener('error',()=>{if($('#movieFrame')===f){window.NoirLoading?.fail('Couldn’t open this source.');setSourceStatus('Couldn’t open '+provider+'. Try Next source.')}});
 $('#screen').replaceChildren(f);
 sourceTimer=setTimeout(()=>{if($('#movieFrame')===f)setSourceStatus('If playback stalls, tap Next source to try another provider.')},18000);
}
function nextSource(){if(!playing)return;const ps=NoirProviders.providers;provider=ps[(ps.findIndex(p=>p.name===provider)+1)%ps.length].name;write('provider',provider);loadPlayer();toast('Trying '+provider)}
$('#nextSource').onclick=nextSource;
async function watch(m,selection){
 setPlayerPresentation(m);$('#detail').close();detailMovie=null;playing=m;$('#playingTitle').textContent=m.name;
 const explicit=selection&&typeof selection==='object'&&Number.isInteger(selection.season)&&Number.isInteger(selection.episode),last=recent.find(x=>x.id===m.id);
 $('#season').value=explicit?selection.season:last?.season||1;$('#episode').value=explicit?selection.episode:last?.episode||1;
 window.NoirLoading?.show(m);window.NoirEpisodeUI?.setPlayer(m,Number($('#season').value),Number($('#episode').value));
 if(!$('#player').open)$('#player').showModal();
 if(!m.tmdb){try{m=await getMeta(m);if(playing?.id!==m.id)return;playing=m;setPlayerPresentation(m)}catch{if(playing?.id!==m.id)return;window.NoirLoading?.fail('Couldn’t load this title. Please try again.');return}}
 if(!$('#player').open||playing?.id!==m.id)return;loadPlayer();remember(m)
}
function trailer(m,index=0){let id=trailerIds(m)[Number(index)||0];if(!id||!/^[\w-]{11}$/.test(id)){toast('No trailer available for this title');return}window.NoirLoading?.hide();window.NoirEpisodeUI?.setPlayer({...m,type:'movie'},1,1);setPlayerPresentation(m);$('#sourceToggle').hidden=true;$('#detail').close();detailMovie=null;playing=null;clearTimeout(sourceTimer);$('.playback-status').hidden=true;$('#playingTitle').textContent=m.name+' · Official trailer';$('#episodeControls').hidden=true;$('.sourcebar').hidden=true;$('#screen').innerHTML=`<iframe title="Official trailer" src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;$('#player').showModal();}
function closePlayer(){$('#player').close();}
$('#player').addEventListener('close',()=>{window.NoirLoading?.hide();window.NoirEpisodeUI?.close(false);$('#screen').replaceChildren();$('.sourcebar').hidden=false;$('.playback-status').hidden=false;clearTimeout(sourceTimer);setSourceStatus('');playing=null;});
$('#detail').addEventListener('close',()=>{detailMovie=null;});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.close){$('#'+b.dataset.close).close();return}if(b.dataset.action){let m=allKnown.get(b.dataset.id)||saved.find(x=>x.id===b.dataset.id)||recent.find(x=>x.id===b.dataset.id);if(!m)return;({watch,detail:showDetail,save,trailer,episodes:showEpisodeChoices})[b.dataset.action]?.(m,b.dataset.trailer)}if(b.dataset.slide){heroIndex=(heroIndex+Number(b.dataset.slide)+heroMovies().length)%heroMovies().length;renderHero()}if(b.dataset.provider){if(!playing)return;provider=b.dataset.provider;write('provider',provider);loadPlayer()}if(b.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderCards()}if(b.dataset.nav)switchNav(b.dataset.nav)});
$('.close-player').onclick=closePlayer;$('#retry').onclick=()=>{loadPlayer();toast('Reloading '+provider)};
async function switchNav(n){nav=n;filter='All';query='';$('#search').value='';searchVersion++;searchController?.abort();$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===n));if(n==='TV Series'&&!tvCatalog.length){$('#status').textContent='Finding your next series…';try{let r=await fetch('https://v3-cinemeta.strem.io/catalog/series/top.json',{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();tvCatalog=register((await r.json()).metas||[])}catch{if(nav===n){$('#cards').innerHTML='';$('#status').textContent='Series could not load. Select TV Series to retry.';}return}}renderCards()}
async function search(){const version=++searchVersion;searchController?.abort();query=$('#search').value.trim();if(!query){renderCards();return}let q=query,type=nav==='TV Series'?'series':'movie';activeCatalog=(type==='series'?tvCatalog:catalog).filter(m=>m.name.toLowerCase().includes(q.toLowerCase()));renderCards();$('#status').textContent='Searching the catalogue…';searchController=new AbortController();let timeout=setTimeout(()=>searchController?.abort(),15000);try{let r=await fetch(`https://v3-cinemeta.strem.io/catalog/${type}/top/search=${encodeURIComponent(q)}.json`,{signal:searchController.signal});if(!r.ok)throw Error();let d=await r.json();if(version!==searchVersion)return;activeCatalog=register(d.metas||[]);renderCards()}catch{if(version===searchVersion){renderCards();$('#status').textContent=activeCatalog.length?'Showing local matches. Online search is temporarily unavailable.':'Online search couldn’t connect. Please try again.'}}finally{clearTimeout(timeout)}}
$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchVersion++;searchController?.abort();searchTimer=setTimeout(search,350)});
$('#seeAll').onclick=()=>{filter='All';$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));renderCards();$('#cards').scrollIntoView({behavior:'smooth',block:'start'})};
function about(){$('#detail').classList.remove('title-page');$('#detailContent').innerHTML='<div class="notice"><button class="icon" data-close="detail" aria-label="Close">✕</button><h2>Your personal cinema.</h2><p>Browse movies, watch official trailers, and keep your watchlist on this device.</p><p>Full playback offers ScreenScape, YapGrid, Braflix, EmbedWave and Stellar. Embedded players are restricted from opening pop-up windows or navigating this page. A provider can still show ads or navigate inside its own frame; try another source if it does. Availability and speed vary. NOIR does not host videos. Watch only content you’re authorized to access.</p><p>Supported players can share playback progress with NOIR to support resume. Other sources may keep progress inside their own player. Your watchlist and recent titles stay in this browser.</p></div>';$('#detail').showModal()}
$('#about').onclick=about;$('#profile').onclick=()=>$('#account').showModal();
window.addEventListener('message',e=>{
 const f=$('#movieFrame'),p=NoirProviders.get(provider);
 if(!p||!playing||e.origin!==p.origin||e.source!==f?.contentWindow)return;
 if(provider==='Stellar'&&e.data?.type==='STELLAR_EMBED_READY'){f.contentWindow.postMessage({type:'STELLAR_EMBED_INIT'},e.origin);return}
 if(p.events&&e.data?.type==='PLAYER_EVENT'){
  const data=e.data.data;if(!data||typeof data!=='object')return;
  const id=data.mtmdbId??data.tmdbId;if(id!=null&&Number(id)!==Number(playing.tmdb))return;
  const time=Number(data.currentTime);if(!Number.isFinite(time)||time<0)return;
  const item=recent.find(x=>x.id===playing.id);
  if(item){item.position=time;item.provider=provider;if(Number.isInteger(data.season))item.season=data.season;if(Number.isInteger(data.episode))item.episode=data.episode;write('recent',recent);renderRecent()}
  if(data.event==='play'||data.event==='timeupdate'){window.NoirLoading?.hide();clearTimeout(sourceTimer);setSourceStatus('Playing with '+provider)}
 }
});
(async()=>{try{let r=await fetch('catalog.json');if(!r.ok)throw Error();catalog=register(await r.json());register(saved);register(recent);renderHero();renderTrailers();renderRecent();renderCards()}catch{$('#status').textContent='The catalogue could not load. Please refresh the page.'}})();
